def generate_pieces(W, H, N, A, B):
    pieces = []
    for i in range(A + 1):
        for j in range(B + 1):
            x = i * (W - 1) + 1
            y = j * (H - 1) + 1
            if (x, y) not in pieces:
                pieces.append((x, y))
    return pieces

def is_good(graph):
    for i in range(1, graph.num_vertices() + 1):
        for j in range(i + 1, graph.num_vertices() + 1):
            if graph.has_path(i, j):
                return False
    return True

