    candidates = [A_i for A_i in range(1, N + 1)]
    winner = None
    for i in range(1, M + 1):
        candidates_with_votes = [A_i for A_i in range(1, N + 1) if A_i in candidates]
        if len(candidates_with_votes) == i:
            winner = max(candidates_with_votes)
