            for j in range(1, H + 1):
                grid[j][i] = 1
        elif i == 2:
            for j in range(1, W + 1):
                grid[j][i] = 1
        else:
            for j in range(1, H + 1):
                for k in range(1, W + 1):
                    grid[j][k] = 1
    return grid

