    for i in range(N):
        A_i, C_i = input().split()
        A_i = int(A_i)
        C_i = int(C_i)
        if A_i > A_i + 1:
            remaining_cards.append(A_i)
        else:
            break
    return remaining_cards

def check_consecutive_elements(A, B):
    C = sorted(A + B)
    for i in range(len(C) - 1):
        if C[i] == C[i + 1]:
            return True
    return False

def bingo_checker(N, T, A_1, A_2, ..., A_T):
    grid = [[0 for _ in range(N)] for _ in range(N)]
    for i in range(T):
        grid[A_i // N][A_i % N] = 1
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 1:
                for k in range(i + 1, N + 1):
                    if grid[k][j] == 1:
                        return i
    return -1

