        return 1
    else:
        return -1

def redistribute_apples(apple, capacity):
    n = len(apple)
    m = len(capacity)
    if n == 0 or m == 0:
        return 0
    if n > m:
        return redistribute_apples(apple, capacity[:n])
    elif n < m:
        return redistribute_apples(apple[:n], capacity)
    else:
        return redistribute_apples(apple[:n], capacity[:m])

